const input = $input.first().json;

// Check if this is a thread reply (has messages array from HTTP request) or new message (webhook)
const isThread = input.messages && Array.isArray(input.messages);

if (isThread) {
  // Thread reply - full context from HTTP request
  const messages = input.messages;

  const latestUserMessage = messages
    .filter(msg => !msg.bot_id)
    .slice(-1)[0];

  const parentMessage = messages[0];

  const recentMessages = messages.slice(-4).map(msg => ({
    user: msg.bot_id ? 'RAG Bot' : `<@${msg.user}>`,
    user_id: msg.user,
    text: msg.text
  }));

  const userIds = [...new Set(messages
    .filter(msg => !msg.bot_id)
    .map(msg => msg.user))];

  return {
    latestMessage: latestUserMessage.text,
    latestMessageUserId: latestUserMessage.user,
    parentMessage: parentMessage.text,
    parentMessageUserId: parentMessage.user,
    threadContext: recentMessages,
    allUserIds: userIds,
    messageCount: messages.length
  };
} else {
  // New message in channel - from webhook
  const event = input.body?.event || input.event || input;

  return {
    latestMessage: event.text,
    latestMessageUserId: event.user,
    parentMessage: null,
    parentMessageUserId: null,
    threadContext: [],
    allUserIds: [event.user],
    messageCount: 1
  };
}

// =========================================================================
// METADATA BOOST — re-rank Pinecone results by tenant-defined signals.
//
// This is the ONLY ranking decision between Pinecone and the LLM.
// Tune weights for YOUR corpus by running eval/run_eval.py before/after.
// =========================================================================

// ─── CONFIG: tune per tenant ───────────────────────────────────────────────
const PRIMARY_TAG          = "verified";  // matches PRIMARY_REACTION_TAG env in ingest
const W_PRIMARY_TAG        = 1.40;        // boost for vectors tagged primary
const W_TRUSTED_AUTHOR     = 1.30;        // boost when a trusted-role author replied
const W_MULTI_TRUSTED      = 1.05;        // small additional boost for 2+ trusted authors
const W_SYNTHETIC_SUMMARY  = 1.10;        // boost for synthesized Q+A summary vectors
const W_HAS_IMAGES         = 1.05;        // boost for chunks derived from image-rich docs
const FINAL_TOP_K          = 10;          // how many to return after boost

// ─── Read incoming matches (Pinecone n8n node shape) ──────────────────────
const items = $input.all();
let matches;
if (items.length === 1 && Array.isArray(items[0].json.matches)) {
  matches = items[0].json.matches.map(m => ({ json: m }));
} else if (items.length === 1 && Array.isArray(items[0].json.documents)) {
  matches = items[0].json.documents.map(m => ({ json: m }));
} else {
  matches = items;
}

// ─── Apply boosts ─────────────────────────────────────────────────────────
const boosted = matches.map(item => {
  const obj = item.json || {};
  const m = obj.metadata || obj.pageContent_metadata || {};
  let score = obj.score ?? obj._score ?? 0;
  const reasons = [];

  if ((m.tags || []).includes(PRIMARY_TAG)) {
    score *= W_PRIMARY_TAG;
    reasons.push(":" + PRIMARY_TAG + ":");
  }
  const trustedCount = ((m.author_roles || {}).trusted) || 0;
  if (trustedCount > 0) {
    score *= W_TRUSTED_AUTHOR;
    reasons.push("trusted");
  }
  if (trustedCount > 1) {
    score *= W_MULTI_TRUSTED;
    reasons.push("multi-trusted");
  }
  if (m.synth === true || m.doc_type === "thread_synth") {
    score *= W_SYNTHETIC_SUMMARY;
    reasons.push("synth");
  }
  if (m.has_images === true) {
    score *= W_HAS_IMAGES;
    reasons.push("images");
  }

  return {
    chunk_text: obj.text || m.text || obj.pageContent || "",
    metadata: m,
    score,
    boost_multiplier: Number((score / (obj.score ?? 1)).toFixed(2)),
    boost_reasons: reasons.length ? reasons.join(", ") : "none",
  };
});

boosted.sort((a, b) => b.score - a.score);
const topResults = boosted.slice(0, FINAL_TOP_K);

// IMPORTANT: return a single item with a `chunks` array (not N items).
// Returning N items causes the downstream agent to run N times and breaks
// pairedItem tracking. Reference this output with `.first()`, not `.item`.
return [{ json: { chunks: topResults, chunk_count: topResults.length } }];
